import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")
    if platform.system() == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["top", "-bn1"]
    records = []
    end_time = time.time() + duration
    while time.time() < end_time:
        timestamp = time.time()
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output = result.stdout.decode()
        if platform.system() == "Windows":
            lines = output.strip().split("\n")
            if len(lines) > 1:
                usage = lines[1].strip()
                if usage.isdigit():
                    records.append({"timestamp": timestamp, "cpu_usage": float(usage)})
        else:
            lines = output.split("\n")
            for line in lines:
                if "%Cpu(s):" in line:
                    parts = line.split(",")
                    idle = float(parts[3].split()[0])
                    usage = 100.0 - idle
                    records.append({"timestamp": timestamp, "cpu_usage": usage})
                    break
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
        return None

import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError("File not found")
    def run_script():
        subprocess.run(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)
    if thread.is_alive():
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

